-- Stories in more languages: a JSON with a version per language, for example
-- { "en": { "titolo", "sottotitolo", "punti", "ctaTesto" } }. The app shows
-- the version in the user's language, otherwise the base one (Italian).

-- AlterTable
ALTER TABLE "novita" ADD COLUMN "traduzioni" TEXT;

-- The stories already published get their English version (no rows on a new installation)
UPDATE "novita" SET "traduzioni" = '{"en": {"titolo": "It reaches you in your pocket", "sottotitolo": "Notifications on your phone, even with the app closed and the screen locked", "punti": [{"icona": "⏱️", "testo": "Rest over? Your phone tells you, and what comes next, even in your pocket"}, {"icona": "💬", "testo": "Chat messages, reminders and alerts arrive even with the app closed"}, {"icona": "📱", "testo": "On iPhone, first add the app to the Home screen, then turn them on in Profile"}], "ctaTesto": "Turn on notifications"}}' WHERE "titolo" = 'Ti avvisa anche in tasca' AND "traduzioni" IS NULL;
UPDATE "novita" SET "traduzioni" = '{"en": {"titolo": "Even without signal", "sottotitolo": "At the gym the network comes and goes: your workout doesn''t", "punti": [{"icona": "✅", "testo": "Log your sets as always, even offline: they stay saved on your phone"}, {"icona": "📶", "testo": "When the network is back they''re sent on their own, once, with the time you did them"}, {"icona": "🏁", "testo": "You can even finish the workout offline: duration and records come out right"}], "ctaTesto": "Start a workout"}}' WHERE "titolo" = 'Anche senza campo' AND "traduzioni" IS NULL;
UPDATE "novita" SET "traduzioni" = '{"en": {"titolo": "Warm-up and drop sets", "sottotitolo": "Only the sets that matter count", "punti": [{"icona": "🔥", "testo": "Before the first set the app suggests a warm-up ramp: one tap for each step you''ve done"}, {"icona": "↘️", "testo": "Drop sets: add the weight drops to a set before logging it"}, {"icona": "📊", "testo": "Warm-ups no longer inflate volume, sets and records. In History, change a set''s type by tapping its number"}], "ctaTesto": "Start a workout"}}' WHERE "titolo" = 'Riscaldamento e drop set' AND "traduzioni" IS NULL;
UPDATE "novita" SET "traduzioni" = '{"en": {"titolo": "The Telegram bot is here", "sottotitolo": "Create and check your plans right from Telegram", "punti": [{"icona": "💬", "testo": "Create plans by chatting with the bot while you train"}, {"icona": "📋", "testo": "Read and download your plans anywhere"}, {"icona": "🔥", "testo": "Add cardio and warm-up by typing"}], "ctaTesto": "Link Telegram"}}' WHERE "titolo" = 'Il bot Telegram è arrivato' AND "traduzioni" IS NULL;
